export const getGithubSelectionUrl = (orgId: number,
    params: GithubSelectionParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/orgs/${orgId}/github/selection?${stringifiedParams}` : `/api/orgs/${orgId}/github/selection`
}

export const githubSelection = async (orgId: number,
    params: GithubSelectionParams, options?: RequestInit): Promise<githubSelectionResponse> => {
  
  return conduxFetch<githubSelectionResponse>(getGithubSelectionUrl(orgId,params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





